  int low = 0;
  int mid = (low + high) / 2;
  boolean found = false;
  while( !found && low <= high){
    mid = (low + high) / 2;
    if( nums[mid] < tgt )
      low = mid + 1;
    else if( nums[mid] > tgt )
      high = mid - 1;
    else
